/* ==========================================================================
 * MediBot Engine  —  Hindi / Hinglish appointment slot extraction
 * --------------------------------------------------------------------------
 * SOURCE OF TRUTH for all bot logic.
 *   - Runs in Node.js            (module.exports)
 *   - Runs inside an n8n Code node (generated by scripts/build-n8n-code.js)
 *
 * Nothing in this file touches the network, the database or the filesystem,
 * so it can be unit-tested with plain `node --test`.
 * ========================================================================== */

'use strict';

/* Copied from doctor-bot-audio/lib/bot-engine.js - the source of truth.
 * Re-copy after changing the engine there:
 *   cp doctor-bot-audio/lib/bot-engine.js doctor-bot-backend/bot-engine.js
 */

const BotEngine = (function () {

  // ------------------------------------------------------------------ CONFIG
  const CONFIG = {
    clinic: {
      openHour: 9,          // 9:00 AM first appointment
      closeHour: 21,        // 9:00 PM last appointment
      closedDays: [0],      // 0 = Sunday -> clinic closed
      maxDaysAhead: 90,     // don't book more than 3 months out
    },
    maxAttemptsPerQuestion: 3, // 3 tries in a row with no progress -> give up
    maxTranscriptLength: 500,
  };

  // ------------------------------------------------------------------ TEXT
  const DEVANAGARI_DIGITS = { '०': '0', '१': '1', '२': '2', '३': '3', '४': '4', '५': '5', '६': '6', '७': '7', '८': '8', '९': '9' };

  function normalize(input) {
    let s = (input == null ? '' : String(input));
    s = s.replace(/[०-९]/g, d => DEVANAGARI_DIGITS[d] || d);
    s = s.replace(/[\u200b\u200c\u200d\ufeff]/g, '');     // zero-width junk
    s = s.replace(/\s+/g, ' ').trim();
    if (s.length > CONFIG.maxTranscriptLength) s = s.slice(0, CONFIG.maxTranscriptLength);
    return s;
  }

  function lower(input) { return normalize(input).toLowerCase(); }

  /** Escape text before putting it inside TwiML/XML (<Say>). Never trust speech-to-text. */
  function escapeXml(value) {
    return String(value == null ? '' : value)
      .replace(/&/g, '&amp;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;')
      .replace(/'/g, '&apos;');
  }

  // ------------------------------------------------------------- NUMBER WORDS
  const WORD_NUMS = {
    ek: 1, do: 2, teen: 3, chaar: 4, char: 4, panch: 5, paanch: 5, chah: 6, chhah: 6, che: 6,
    saat: 7, sat: 7, aath: 8, ath: 8, nau: 9, no: 9, das: 10, dus: 10, dasa: 10,
    gyarah: 11, gyarha: 11, barah: 12, bara: 12, baarah: 12,
    एक: 1, दो: 2, तीन: 3, चार: 4, पाँच: 5, पांच: 5, छह: 6, छे: 6,
    सात: 7, आठ: 8, नौ: 9, दस: 10, ग्यारह: 11, बारह: 12,
    one: 1, two: 2, three: 3, four: 4, five: 5, six: 6, seven: 7, eight: 8, nine: 9, ten: 10, eleven: 11, twelve: 12,
  };

  /** "10" or "das" -> 10. Returns null when not a number. */
  function toNumber(token) {
    if (token == null) return null;
    const t = normalize(token).toLowerCase();
    if (/^\d{1,2}$/.test(t)) return parseInt(t, 10);
    if (Object.prototype.hasOwnProperty.call(WORD_NUMS, t)) return WORD_NUMS[t];
    return null;
  }

  const NUM_WORD_RE = Object.keys(WORD_NUMS).join('|');

  // ------------------------------------------------------------------ NAME
  const HONORIFICS = /^(dr|dr\.|doctor|mr|mr\.|mrs|mrs\.|ms|ms\.|miss|shri|shree|shrimati|smt|ji|डॉ|डॉक्टर|डा|श्री|श्रीमती|जी|साहब|साहिब)\s+/i;

  const NOT_NAMES = new Set([
    // dates & times
    'aaj', 'aj', 'kal', 'kl', 'parso', 'parson', 'आज', 'कल', 'परसों', 'subah', 'सुबह', 'shaam', 'sham', 'शाम', 'dopahar', 'दोपहर',
    'raat', 'रात', 'morning', 'evening', 'afternoon', 'night', 'baje', 'बजे', 'today', 'tomorrow', 'week', 'month',
    // symptoms
    'bukhar', 'bukhaar', 'बुखार', 'khansi', 'खांसी', 'sardi', 'सर्दी', 'dard', 'दर्द', 'fever', 'cough', 'pain', 'checkup',
    'चेकअप', 'जाँच', 'जांच', 'दवाई', 'दवा', 'तकलीफ', 'समस्या', 'problem', 'बीमार', 'bimar', 'hospital', 'अस्पताल', 'clinic',
    // filler / yes-no
    'haan', 'han', 'ha', 'yes', 'nahi', 'nahin', 'na', 'no', 'नहीं', 'हाँ', 'हां', 'naa', 'theek', 'thik', 'ok', 'okay',
    'अच्छा', 'achha', 'acha', 'hello', 'hallo', 'helo', 'हेलो', 'नमस्ते', 'namaste', 'namaskar', 'sir', 'madam', 'ji', 'जी',
    // meta words
    'appointment', 'अपॉइंटमेंट', 'doctor', 'डॉक्टर', 'patient', 'mujhe', 'mera', 'meri', 'मेरा', 'मेरी', 'mujhko', 'karna',
    'karni', 'chahiye', 'चाहिए', 'batao', 'बताओ', 'please', 'प्लीज़', 'kuch', 'कुछ', 'koi', 'कोई', 'bhi', 'भी', 'बताइए',
    'बताएं', 'बताए', 'sakta', 'sakti', 'sorry', 'सॉरी', 'thanks', 'dhanyavad', 'धन्यवाद', 'number', 'नंबर',
    'kyun', 'kyu', 'क्यों', 'kya', 'क्या', 'kaise', 'कैसे', 'kaun', 'कौन', 'kab', 'कब',
  ]);

  // Words that must never be swallowed as part of a name.
  const NAME_STOPWORDS = new Set([
    'hai', 'hoon', 'hun', 'hu', 'है', 'हूँ', 'हूं', 'ke', 'ki', 'ka', 'के', 'की', 'का', 'ko', 'को', 'se', 'से', 'aur', 'और',
    'liye', 'लिए', 'ke liye', 'mera', 'meri', 'mere', 'मेरा', 'मेरी', 'मेरे', 'mujhe', 'मुझे', 'unka', 'unki', 'uska', 'uski',
    'उनका', 'उनकी', 'उसका', 'उसकी', 'naam', 'नाम', 'baje', 'बजे', 'ko', 'wala', 'wali', 'वाला', 'वाली',
  ]);

  const NAME_PATTERNS = [
    // "mera naam Priya Sharma hai"
    /(?:mera|meri|mai|main|मेरा|मेरी|मैं)\s+naam\s+(?:is\s+)?(?:Dr\.?\s+)?(.+)/i,
    // "naam Priya hai" / "नाम प्रिया है"
    /(?:naam|नाम)\s+(?:is\s+)?(.+)/i,
    // "unka naam Priya hai"
    /(?:unka|unki|uska|uski|inka|inki|उनका|उनकी|उसका|उसकी)\s+(?:naam|नाम)\s+(.+)/i,
    // "meri mummy ka naam Priya hai"
    /(?:meri|mere|मेरी|मेरे)\s+(?:mummy|mami|maa|ma|mata|papa|pita|baap|beti|beta|bacche|bachche|dadi|dada|nani|nana|patni|pati|bhai|behen|बहन|मां|माँ|मम्मी|पापा|पिता|बेटी|बेटे|बच्चे|दादी|दादा|नानी|नाना|पत्नी|पति|भाई)\s+(?:ka|ki|ke|का|की|के)\s+(?:naam|नाम)\s+(.+)/i,
    // "Priya ke liye appointment"  (name itself)
    /^([a-z\u0900-\u097F][a-z\u0900-\u097F\s]{1,40}?)\s+(?:ke|ki|के|की)\s+(?:liye|लिए)/i,
    // "Priya bol rahi hoon"
    /^(.+?)\s+(?:bol|bool|बोल)\s+rah/i,
    // "meri mummy Priya ke liye" -> relation then name
    /(?:mummy|mami|maa|ma|papa|pitaji|pita|beti|beta|bacche|dadi|dada|nani|nana|patni|pati|bhai|behen|मां|माँ|मम्मी|पापा|बेटी|बेटे|बच्चे|दादी|दादा|नानी|नाना|पत्नी|पति|भाई|बहन)\s+(?:ka|ki|ke|का|की|के)\s+(?:liye|लिए|naam|नाम)\s+(.+)/i,
    // "Priya Sharma, kal 10 baje"
    /^([a-z\u0900-\u097F]+(?:\s+[a-z\u0900-\u097F]+)?)\s*[,।]/i,
  ];

  function cleanName(raw) {
    if (!raw) return null;
    let s = normalize(raw);
    s = s.replace(/[.,!?।]+$/g, '').trim();
    s = s.replace(HONORIFICS, '');
    s = s.replace(/\s+(ji|जी|sahab|साहब)$/i, '').trim();

    const words = s.split(' ').filter(Boolean);
    const kept = [];
    for (const w of words) {
      const wl = w.toLowerCase().replace(/[.,!?।]/g, '');
      if (NAME_STOPWORDS.has(wl)) break;          // "Priya hai" -> stop at "hai"
      if (NOT_NAMES.has(wl)) break;
      if (/^\d+$/.test(wl)) break;                 // no digits in a name
      kept.push(w.replace(/[.,!?।]/g, ''));
      if (kept.length === 3) break;                // at most 3 words
    }
    if (kept.length === 0) return null;
    let name = kept.join(' ').trim();
    if (name.length < 2) return null;
    if (name.length > 40) return null;
    if (NOT_NAMES.has(name.toLowerCase())) return null;
    // Speech-to-text returns lowercase; make "priya sharma" -> "Priya Sharma" for the sheet.
    if (/^[a-z][a-z\s.'-]*$/.test(name)) {
      name = name.split(' ').map(w => w.charAt(0).toUpperCase() + w.slice(1)).join(' ');
    }
    return name;
  }

  /** Runs the patterns on the ORIGINAL text so "Priya Sharma" keeps its capital letters. */
  function extractName(raw) {
    const text = normalize(raw);
    for (const re of NAME_PATTERNS) {
      const m = text.match(re);
      if (m && m[1]) {
        const name = cleanName(m[1]);
        if (name) return name;
      }
    }
    // Bare answer to "aapka naam kya hai?" e.g. caller just says "Priya Sharma".
    // Only allowed when the bot actually asked for the name (caller passes asked_field).
    return null;
  }

  // ------------------------------------------------------------- RELATION
  const RELATIONS = [
    { words: ['मम्मी', 'मां', 'माँ', 'माता', 'mummy', 'mami', 'ammi', 'maa', 'ma'], value: 'Mother' },
    { words: ['पापा', 'पिता', 'papa', 'pita', 'papa ji', 'pita ji', 'baap', 'dad', 'father'], value: 'Father' },
    { words: ['बेटी', 'beti', 'girl', 'daughter'], value: 'Daughter' },
    { words: ['बेटा', 'बेटे', 'beta', 'ladka', 'son'], value: 'Son' },
    { words: ['बच्चा', 'बच्ची', 'बच्चे', 'baccha', 'bachcha', 'bacche', 'child', 'baby'], value: 'Child' },
    { words: ['दादी', 'dadi', 'grandmother', 'nani', 'नानी'], value: 'Grandmother' },
    { words: ['दादा', 'dada', 'grandfather', 'nana', 'नाना'], value: 'Grandfather' },
    { words: ['पत्नी', 'patni', 'wife', 'biwi'], value: 'Wife' },
    { words: ['पति', 'pati', 'husband'], value: 'Husband' },
    { words: ['भाई', 'bhai', 'brother'], value: 'Brother' },
    { words: ['बहन', 'बहिन', 'behen', 'bahen', 'sister'], value: 'Sister' },
    { words: ['भतीजा', 'भतीजी', 'bhatija', 'bhatiji'], value: 'Nephew/Niece' },
    { words: ['अंकल', 'ankal', 'uncle', 'mama ji', 'chacha', 'chachi', 'ताऊ', 'ताई'], value: 'Relative' },
    { words: ['आंटी', 'aunty', 'aanti', 'mausi', 'बुआ'], value: 'Relative' },
  ];

  function detectRelation(t) {
    const words = t.split(/[^\p{L}\p{N}]+/u).filter(Boolean);
    for (const rel of RELATIONS) {
      for (const w of rel.words) {
        if (/^[a-z]+$/.test(w)) {
          if (words.includes(w)) return rel.value;            // exact latin word
        } else if (t.includes(w)) {
          return rel.value;
        }
      }
    }
    return 'Self';
  }

  // ------------------------------------------------------------------ DATE
  const MONTHS = [
    { hi: 'जनवरी', en: 'january', n: 1 }, { hi: 'फरवरी', en: 'february', n: 2 }, { hi: 'मार्च', en: 'march', n: 3 },
    { hi: 'अप्रैल', en: 'april', n: 4 }, { hi: 'मई', en: 'may', n: 5 }, { hi: 'जून', en: 'june', n: 6 },
    { hi: 'जुलाई', en: 'july', n: 7 }, { hi: 'अगस्त', en: 'august', n: 8 }, { hi: 'सितंबर', en: 'september', n: 9 },
    { hi: 'अक्टूबर', en: 'october', n: 10 }, { hi: 'नवंबर', en: 'november', n: 11 }, { hi: 'दिसंबर', en: 'december', n: 12 },
  ];
  const MONTH_ALIASES = {
    jan: 1, feb: 2, mar: 3, apr: 4, jun: 5 + 1, jul: 7, aug: 8, sept: 9, sep: 9, oct: 10, nov: 11, dec: 12,
    joon: 6, janvari: 1, farvari: 2, aprail: 4, sitambar: 9, october: 10, navambar: 11, disambar: 12,
  };
  const DAY_NAMES = [
    { hi: 'रविवार', en: 'sunday', d: 0 }, { hi: 'सोमवार', en: 'monday', d: 1 }, { hi: 'मंगलवार', en: 'tuesday', d: 2 },
    { hi: 'बुधवार', en: 'wednesday', d: 3 }, { hi: 'गुरुवार', en: 'thursday', d: 4 }, { hi: 'शुक्रवार', en: 'friday', d: 5 },
    { hi: 'शनिवार', en: 'saturday', d: 6 },
  ];
  const DAY_ALIASES = { ravivar: 0, somvar: 1, somwar: 1, mangalvar: 2, mangalwar: 2, budhvar: 3, budhwar: 3, guruvar: 4, guruwar: 4, shukravar: 5, shukrawar: 5, shanivar: 6, shaniwar: 6, sun: 0, mon: 1, tue: 2, tues: 2, wed: 3, thu: 4, thur: 4, thurs: 4, fri: 5, sat: 6 };

  function mkDate(y, m, d) { return new Date(y, m - 1, d); }
  function daysInMonth(y, m) { return new Date(y, m, 0).getDate(); }
  /** Returns a Date, or null for impossible dates like 31 February / 32 January. */
  function makeValid(y, m, d) {
    if (m < 1 || m > 12) return null;
    if (d < 1 || d > daysInMonth(y, m)) return null;
    return new Date(y, m - 1, d);
  }
  function startOfDay(dt) { return new Date(dt.getFullYear(), dt.getMonth(), dt.getDate()); }
  function dayDiff(a, b) { return Math.round((startOfDay(a) - startOfDay(b)) / 86400000); }

  /** Validates a candidate date. Returns {ok, reason} */
  function validateDate(dt, today) {
    if (!(dt instanceof Date) || isNaN(dt.getTime())) return { ok: false, reason: 'invalid_date' };
    const diff = dayDiff(dt, today);
    if (diff < 0) return { ok: false, reason: 'past_date' };
    if (diff > CONFIG.clinic.maxDaysAhead) return { ok: false, reason: 'too_far' };
    if (CONFIG.clinic.closedDays.includes(dt.getDay())) return { ok: false, reason: 'closed_day' };
    return { ok: true };
  }

  const HI_MONTH_SPEECH = ['जनवरी', 'फरवरी', 'मार्च', 'अप्रैल', 'मई', 'जून', 'जुलाई', 'अगस्त', 'सितंबर', 'अक्टूबर', 'नवंबर', 'दिसंबर'];

  function fmtDate(dt) {
    const dd = String(dt.getDate()).padStart(2, '0');
    const mm = String(dt.getMonth() + 1).padStart(2, '0');
    return {
      value: `${dd}/${mm}/${dt.getFullYear()}`,
      iso: `${dt.getFullYear()}-${mm}-${dd}`,
      speech: `${dt.getDate()} ${HI_MONTH_SPEECH[dt.getMonth()]} ${dt.getFullYear()}`,
    };
  }

  /** "24/06/2026" -> Date */
  function fromEnDate(value) {
    const m = /^(\d{1,2})\/(\d{1,2})\/(\d{4})$/.exec(normalize(value));
    if (!m) return null;
    const dt = mkDate(parseInt(m[3], 10), parseInt(m[2], 10), parseInt(m[1], 10));
    return isNaN(dt.getTime()) ? null : dt;
  }

  function speechForDateValue(value) {
    const dt = fromEnDate(value);
    return dt ? fmtDate(dt).speech : null;
  }

  function isoForDateValue(value) {
    const dt = fromEnDate(value);
    return dt ? fmtDate(dt).iso : null;
  }

  /** "Morning 10:00" -> "सुबह 10 बजे" (used when only the short value survived the URL) */
  function speechForSlot(slot) {
    const m = /^(Morning|Afternoon|Evening|Night)\s+(\d{1,2}):(\d{2})$/.exec(normalize(slot));
    if (!m) return slot || null;
    const h = parseInt(m[2], 10), min = parseInt(m[3], 10);
    return `${speechPeriod(h)} ${h % 12 === 0 ? 12 : h % 12}${min ? ' ' + min : ''} बजे`;
  }

  /** Removes clock expressions so "subah 10.30 baje" is never mistaken for a date. */
  function stripTimeExpressions(t) {
    let s = ' ' + t + ' ';
    s = s.replace(/\d{1,2}\s*[:.]\s*\d{2}\s*(?:baje|baj|बजे|am|pm|a\.m\.|p\.m\.)?/gi, ' ');
    s = s.replace(/\b(?:subah|subha|subh|सुबह|dopahar|dophr|dopar|दोपहर|shaam|sham|shyaam|shyam|sam|saam|शाम|raat|rat|रात|morning|afternoon|noon|evening|night)\b[\s\w]{0,12}?(?:baje|baj|बजे|o'?clock)\b/gi, ' ');
    s = s.replace(/\b(?:subah|subha|subh|सुबह|dopahar|dophr|dopar|दोपहर|shaam|sham|shyaam|shyam|sam|saam|शाम|raat|rat|रात|morning|afternoon|noon|evening|night)\s+(\d{1,2})\b/gi, ' ');
    s = s.replace(/\b(\d{1,2})\s*(?:baje|baj|बजे|o'?clock)\b/gi, ' ');
    s = s.replace(/\b\d{1,2}\s*(?:am|pm|a\.m\.|p\.m\.)\b/gi, ' ');
    return s.replace(/\s+/g, ' ').trim();
  }

  /** True when the transcript looks like the caller was trying to say a date. */
  function looksLikeDateAttempt(t) {
    return /(aaj|aj|kal|kl|parso|parson|आज|कल|परसों|today|tomorrow|tarikh|तारीख|date|din|दिन|ko|को|agle|अगले|next|week|month|hafte|mahine|\d{1,2}\s*[\/\-.]\s*\d{1,2}|\d{1,2}\s*(?:tarikh|तारीख)|\d{1,2}\s*(?:jan|feb|mar|apr|may|jun|jul|aug|sep|oct|nov|dec|january|february|march|april|june|july|august|september|october|november|december))/.test(t)
      || DAY_NAMES.some(d => t.includes(d.en) || t.includes(d.hi))
      || Object.keys(DAY_ALIASES).some(a => t.includes(a));
  }

  /** Returns {status:'ok'|'invalid'|'past_date'|'closed_day'|'too_far'|'none', dt, info} */
  function parseDate(input, today) {
    today = startOfDay(today || new Date());
    const t = stripTimeExpressions(input);

    // ---- relative words ----
    if (/(?:^|\s)(aaj|aj|आज|today)(?:\s|$)/.test(t)) return fromCandidate(today, today);
    if (/(?:^|\s)(kal|kl|कल|tomorrow)(?:\s|$)/.test(t)) { const d = new Date(today); d.setDate(d.getDate() + 1); return fromCandidate(d, today); }
    if (/(?:^|\s)(parso|parson|परसों)(?:\s|$)/.test(t)) { const d = new Date(today); d.setDate(d.getDate() + 2); return fromCandidate(d, today); }

    // "next week" / "agle hafte"
    const nextWeek = /(next\s+week|agle\s+hafte|agli\s+hafte|अगले\s+हफ्ते|अगले\s+सप्ताह)/.test(t);
    if (nextWeek) { const d = new Date(today); d.setDate(d.getDate() + 7); return fromCandidate(d, today); }

    // "next month" / "agle mahine"
    const nextMonth = /(next\s+month|agle\s+mahine|agli\s+mahine|अगले\s+महीने)/.test(t);
    if (nextMonth) { const d = new Date(today); d.setMonth(d.getMonth() + 1); return fromCandidate(d, today); }

    // ---- explicit DD/MM or DD-MM(-YYYY).  "10.30" is treated as a clock, so a
    //      dot-separated date only counts when it carries a full year. ----
    const numDate = t.match(/(\d{1,2})\s*[\/\-]\s*(\d{1,2})(?:\s*[\/\-]\s*(\d{2,4}))?/)
      || t.match(/(\d{1,2})\.(\d{1,2})\.(\d{4})/);
    if (numDate) {
      let a = parseInt(numDate[1], 10), b = parseInt(numDate[2], 10), y = numDate[3] ? parseInt(numDate[3], 10) : today.getFullYear();
      if (y < 100) y += 2000;
      let day, month;
      if (a > 12 && b <= 12) { day = a; month = b; }          // 24/6  -> DD/MM
      else if (b > 12 && a <= 12) { day = b; month = a; }     // 6/24  -> MM/DD
      else { day = a; month = b; }                            // Indian default DD/MM
      const dt = makeValid(y, month, day);
      if (!dt) return { status: 'invalid_date', reason: 'invalid_date' };
      return fromCandidate(rollForward(dt, today), today);
    }

    // ---- "24 june" / "june 24" / "24 जून" ----
    for (const m of MONTHS) {
      const re = new RegExp(`(\\d{1,2})\\s*(?:st|nd|rd|th)?\\s*(?:of\\s+)?(?:ka\\s+)?(?:${m.en}|${m.hi})`, 'i');
      const re2 = new RegExp(`(?:${m.en}|${m.hi})\\s*(\\d{1,2})(?:\\s*(?:st|nd|rd|th))?`, 'i');
      const hit = t.match(re) || t.match(re2);
      if (hit) {
        const day = parseInt(hit[1], 10);
        const dt = makeValid(today.getFullYear(), m.n, day);
        if (!dt) return { status: 'invalid_date', reason: 'invalid_date' };
        return fromCandidate(rollForward(dt, today), today);
      }
    }
    for (const alias of Object.keys(MONTH_ALIASES)) {
      const re = new RegExp(`(\\d{1,2})\\s*(?:st|nd|rd|th)?\\s*(?:of\\s+)?${alias}\\b`, 'i');
      const hit = t.match(re);
      if (hit) {
        const dt = makeValid(today.getFullYear(), MONTH_ALIASES[alias], parseInt(hit[1], 10));
        if (!dt) return { status: 'invalid_date', reason: 'invalid_date' };
        return fromCandidate(rollForward(dt, today), today);
      }
    }

    // ---- day names (Hindi / English) ----
    for (const d of DAY_NAMES) {
      if (t.includes(d.hi) || new RegExp(`\\b${d.en}\\b`, 'i').test(t)) {
        const days = (d.d - today.getDay() + 7) % 7;          // same day -> today
        const dt = new Date(today); dt.setDate(dt.getDate() + days);
        return fromCandidate(dt, today);
      }
    }
    for (const alias of Object.keys(DAY_ALIASES)) {
      if (new RegExp(`\\b${alias}\\b`, 'i').test(t)) {
        const days = (DAY_ALIASES[alias] - today.getDay() + 7) % 7;
        const dt = new Date(today); dt.setDate(dt.getDate() + days);
        return fromCandidate(dt, today);
      }
    }

    // ---- "5 tarikh" / "tarikh 5" / "5 ko" / "5 date" ----
    const dayNum = t.match(/(?:tarikh|तारीख|date|din|दिन)\s*(\d{1,2})|(\d{1,2})\s*(?:tarikh|तारीख|date\b|ko\b|को\b)/i);
    if (dayNum) {
      const day = parseInt(dayNum[1] || dayNum[2], 10);
      if (day >= 1 && day <= 31) {
        let dt = makeValid(today.getFullYear(), today.getMonth() + 1, day);
        if (!dt || dayDiff(dt, today) < 0) dt = makeValid(today.getFullYear(), today.getMonth() + 2, day);
        if (!dt) return { status: 'invalid', reason: 'invalid_date' };
        return fromCandidate(dt, today);
      }
      return { status: 'invalid_date', reason: 'invalid_date' };
    }

    return { status: 'none' };
  }

  /** If an explicit date already passed this year, assume next year (only when year was not given). */
  function rollForward(dt, today) {
    if (dayDiff(dt, today) < -180) { const d = new Date(dt); d.setFullYear(d.getFullYear() + 1); return d; }
    return dt;
  }

  function fromCandidate(dt, today) {
    if (!(dt instanceof Date) || isNaN(dt.getTime())) return { status: 'invalid', reason: 'invalid_date' };
    const v = validateDate(dt, today);
    if (!v.ok) return { status: v.reason, reason: v.reason };
    return { status: 'ok', dt, info: fmtDate(dt) };
  }

  // ------------------------------------------------------------------ TIME
  // Phonetic map for the classic "shaam -> sam" speech-to-text problem.
  const PERIOD_WORDS = [
    { key: 'morning', words: ['subah', 'subha', 'subh', 'सुबह', 'morning', 'morn'], speech: 'सुबह' },
    { key: 'afternoon', words: ['dopahar', 'dophr', 'dopar', 'dopahra', 'दोपहर', 'afternoon', 'noon'], speech: 'दोपहर' },
    { key: 'evening', words: ['shaam', 'sham', 'shyaam', 'shyam', 'sam', 'saam', 'शाम', 'evening', 'shaah'], speech: 'शाम' },
    { key: 'night', words: ['raat', 'rat', 'रात', 'night'], speech: 'रात' },
  ];

  function findPeriod(t) {
    for (const p of PERIOD_WORDS) {
      for (const w of p.words) {
        if (/^[a-z]+$/.test(w)) {
          if (new RegExp(`\\b${w}\\b`, 'i').test(t)) return p;
        } else if (t.includes(w)) return p;
      }
    }
    return null;
  }

  function fmtTime(h24, min) {
    const hh = String(h24).padStart(2, '0');
    const mm = String(min || 0).padStart(2, '0');
    return `${hh}:${mm}`;
  }

  function periodForHour(h24) {
    if (h24 < 12) return 'Morning';
    if (h24 < 16) return 'Afternoon';
    if (h24 < 19) return 'Evening';
    return 'Night';
  }
  function speechPeriod(h24) {
    if (h24 < 12) return 'सुबह';
    if (h24 < 16) return 'दोपहर';
    if (h24 < 19) return 'शाम';
    return 'रात';
  }

  function looksLikeTimeAttempt(t) {
    return PERIOD_WORDS.some(p => p.words.some(w => (/^[a-z]+$/.test(w) ? new RegExp(`\\b${w}\\b`, 'i').test(t) : t.includes(w))))
      || /baje|baj|बजे|o'?clock|am\b|pm\b/.test(t)
      || /(sava|saadhe|sadhe|paune|paune|सवा|साढ़े|साढे|पौने)/.test(t)
      || /\d{1,2}\s*[:.]\s*\d{2}/.test(t);
  }

  /** Returns {status:'ok'|'invalid'|'out_of_hours'|'none', slot, display, speech} */
  function parseTime(t) {
    const period = findPeriod(t);

    // "sava 5" = 5:15, "saadhe 5" = 5:30, "paune 5" = 4:45
    let offsetMin = 0;
    if (/\b(sava|सवा)\b/.test(t)) offsetMin = 15;
    else if (/\b(saadhe|sadhe|साढ़े|साढे)\b/.test(t)) offsetMin = 30;
    else if (/\b(paune|pune|पौने)\b/.test(t)) offsetMin = -15;

    // hour:minute (10:30 / 10.30)
    let hit = t.match(/(\d{1,2})\s*[:.]\s*(\d{2})/);
    if (hit) {
      let h = parseInt(hit[1], 10), m = parseInt(hit[2], 10);
      if (m > 59) return { status: 'invalid_time', reason: 'invalid_time' };
      return buildTime(h, m, period, t);
    }

    // "<period> <hour>"  or  "<hour> baje"
    const hourWord = `(\\d{1,2}|${NUM_WORD_RE})`;
    hit = t.match(new RegExp(`(?:${'subah|subha|सुबह|morning|dopahar|dophr|दोपहर|afternoon|noon|shaam|sham|shyaam|shyam|sam|saam|शाम|evening|raat|rat|रात|night'})\\s*(?:ke\\s*)?${hourWord}`, 'i'))
      || t.match(new RegExp(`${hourWord}\\s*(?:baje|baj|बजे|o'?clock)`, 'i'));

    if (hit) {
      const h = toNumber(hit[1]);
      if (h == null) return { status: 'invalid_time', reason: 'invalid_time' };
      let m = 0;
      if (offsetMin < 0) { m = 60 + offsetMin; }
      else m = offsetMin;
      let hh = h + (offsetMin < 0 ? -1 : 0);
      return buildTime(hh, m, period, t);
    }

    // am / pm
    hit = t.match(/(\d{1,2})\s*(am|a\.m\.|pm|p\.m\.)/i);
    if (hit) {
      const h = parseInt(hit[1], 10);
      const isPm = /p/i.test(hit[2]);
      if (h > 12) return { status: 'invalid_time', reason: 'invalid_time' };
      return buildTime(h, 0, isPm ? { key: 'evening', speech: 'शाम' } : { key: 'morning', speech: 'सुबह' }, t, isPm);
    }

    // bare 24-hour "14 baje" / "14:00" handled above; bare "14" is too ambiguous -> ignore
    if (period) {
      // period only -> the whole window
      const ranges = {
        morning: { slot: 'Morning', display: 'Morning (9:00-12:00)', speech: 'सुबह 9 से 12 बजे' },
        afternoon: { slot: 'Afternoon', display: 'Afternoon (12:00-16:00)', speech: 'दोपहर 12 से 4 बजे' },
        evening: { slot: 'Evening', display: 'Evening (16:00-19:00)', speech: 'शाम 4 से 7 बजे' },
        night: { slot: 'Night', display: 'Night (19:00-21:00)', speech: 'रात 7 से 9 बजे' },
      };
      const r = ranges[period.key];
      return { status: 'ok', slot: r.slot, display: r.display, speech: r.speech, range: true };
    }

    // "koi bhi / jo bhi / kuch bhi / chalega" -> bot picks morning
    if (/koi\s*bhi|kuch\s*bhi|jo\s*bhi|jab\s*bhi|chalega|chalt[ae]\s*hai|कोई\s*भी|कुछ\s*भी|जब\s*भी|चलेगा|anytime|any\s*time|whenever/.test(t)) {
      return buildTime(10, 0, { key: 'morning', speech: 'सुबह' }, t);
    }

    return { status: 'none' };
  }

  function buildTime(hRaw, min, period, t, forcePm) {
    let h = hRaw;
    const periodKey = period ? period.key : null;

    if (!periodKey && !forcePm) {
      // "10 baje" with no word -> infer from the number
      if (h >= 1 && h <= 11) { period = { key: 'morning', speech: 'सुबह' }; }
      else if (h === 12) { period = { key: 'afternoon', speech: 'दोपहर' }; }
      else if (h >= 13 && h <= 21) { period = null; }              // already 24h
      else return { status: 'invalid_time', reason: 'invalid_time' };
    }

    if (h >= 13 && h <= 24) { h = h === 24 ? 0 : h; }              // 14 baje -> 14:00
    else if (h >= 1 && h <= 12 && period) {
      const isPmPeriod = ['afternoon', 'evening', 'night'].includes(period.key);
      if (isPmPeriod && h < 12) h += 12;
      if (period.key === 'night' && h === 12) h = 0;               // raat 12 = midnight
      if (period.key === 'morning' && h === 12) h = 0;             // subah 12 = midnight
    }

    if (!(h >= 0 && h <= 23) || !(min >= 0 && min <= 59)) return { status: 'invalid_time', reason: 'invalid_time' };

    const closed = h < CONFIG.clinic.openHour || h > CONFIG.clinic.closeHour || (h === CONFIG.clinic.closeHour && min > 0);
    if (closed) {
      // Caller said only "4 baje" -> that is 4 AM (closed), but they almost
      // certainly meant 4 PM. Retry once in the evening before rejecting.
      if (!periodKey && !forcePm && hRaw >= 1 && hRaw <= 8) {
        return buildTime(hRaw + 12, min, { key: 'evening', speech: 'शाम' }, t, true);
      }
      return { status: 'out_of_hours', reason: 'out_of_hours' };
    }

    const label = periodForHour(h);
    const time = fmtTime(h, min);
    return {
      status: 'ok',
      slot: `${label} ${time}`,
      display: `${label} ${time}`,
      speech: `${speechPeriod(h)} ${h % 12 === 0 ? 12 : h % 12}${min ? ' ' + min : ''} बजे`,
      h24: h, min,
    };
  }

  // ---------------------------------------------------------------- REASON
  const SYMPTOM_GROUPS = [
    { key: 'Fever', words: ['bukhar', 'bukhaar', 'बुखार', 'fever', 'temperature', 'बुख़ार'] },
    { key: 'Cough', words: ['khansi', 'khasi', 'खांसी', 'खाँसी', 'cough'] },
    { key: 'Cold', words: ['sardi', 'sardee', 'सर्दी', 'जुकाम', 'jukam', 'cold', 'naak band', 'running nose'] },
    { key: 'Headache', words: ['sir dard', 'sirdard', 'सिरदर्द', 'सिर दर्द', 'headache', 'migraine', 'आधा सिर'] },
    { key: 'Stomach pain', words: ['pet dard', 'petdard', 'पेट दर्द', 'पेट में दर्द', 'stomach', 'pet me dard', 'pet kharab'] },
    { key: 'Back pain', words: ['kamar dard', 'कमर दर्द', 'कमर में दर्द', 'back pain', 'kamar'] },
    { key: 'Tooth pain', words: ['daant dard', 'दांत दर्द', 'दाँत दर्द', 'tooth', 'teeth', 'dant'] },
    { key: 'Throat pain', words: ['gala', 'gale', 'गला', 'गले', 'throat', 'tonsil'] },
    { key: 'Eye problem', words: ['aankh', 'aankhein', 'आँख', 'आंख', 'eye', 'aankhon'] },
    { key: 'Ear problem', words: ['kaan', 'कान', 'ear'] },
    { key: 'Vomiting / Diarrhoea', words: ['ulti', 'उल्टी', 'vomit', 'dast', 'दस्त', 'loose motion'] },
    { key: 'Breathing problem', words: ['saans', 'sans', 'सांस', 'साँस', 'breath', 'dama', 'दमा', 'asthma'] },
    { key: 'Blood pressure', words: ['bp', 'बीपी', 'blood pressure', 'ब्लड प्रेशर'] },
    { key: 'Diabetes / Sugar', words: ['sugar', 'शुगर', 'diabetes', 'डायबिटीज', 'मधुमेह'] },
    { key: 'Weakness', words: ['thakan', 'थकान', 'weakness', 'kamzori', 'कमजोरी', 'kamzor'] },
    { key: 'Injury', words: ['chot', 'चोट', 'injury', 'gir gaya', 'गिर गया', 'मोच', 'moch'] },
    { key: 'Allergy', words: ['allergy', 'एलर्जी', 'rash', 'दाने', 'dane', 'itch', 'खुजली'] },
    { key: 'Skin problem', words: ['twacha', 'त्वचा', 'skin', 'चमड़ी'] },
    { key: 'Joint pain', words: ['jod', 'जोड़', 'joint', 'guthna', 'घुटना', 'knee', 'गठिया'] },
  ];
  const PROCEDURE_WORDS = [
    { key: 'Checkup', words: ['checkup', 'चेकअप', 'जाँच', 'जांच', 'test', 'टेस्ट', 'report', 'रिपोर्ट', 'blood test'] },
    { key: 'Consultation', words: ['dikhana', 'दिखाना', 'दिखाने', 'consult', 'consultation', 'milna', 'मिलना', 'परामर्श'] },
    { key: 'Medicine / Follow-up', words: ['dawai', 'दवाई', 'दवा', 'medicine', 'मेडिसिन', 'prescription'] },
    { key: 'Vaccination', words: ['vaccine', 'वैक्सीन', 'टीका', 'tika', 'injection', 'इंजेक्शन'] },
    { key: 'Follow-up', words: ['follow up', 'फॉलो', 'followup', 'dobara dikhana'] },
  ];
  const VAGUE_DISTRESS = ['tabiyat kharab', 'tabiyat khraab', 'tabiat kharab', 'तबीयत खराब', 'tabiyat theek nahi', 'bimar hu', 'bimar hoon', 'बीमार', 'theek nahi', 'thik nahi', 'health issue', 'problem hai', 'समस्या है', 'दिक्कत'];

  /** Collects up to 3 reasons, so "bukhar aur khansi" keeps both. */
  function extractReason(t) {
    const found = [];
    for (const g of SYMPTOM_GROUPS) {
      if (g.words.some(w => (/^[a-z ]+$/.test(w) ? new RegExp(`\\b${w.replace(/ /g, '\\s+')}\\b`, 'i').test(t) : t.includes(w)))) {
        if (!found.includes(g.key)) found.push(g.key);
      }
    }
    if (found.length === 0) {
      for (const g of PROCEDURE_WORDS) {
        if (g.words.some(w => (/^[a-z ]+$/.test(w) ? new RegExp(`\\b${w.replace(/ /g, '\\s+')}\\b`, 'i').test(t) : t.includes(w)))) {
          if (!found.includes(g.key)) found.push(g.key);
        }
      }
    }
    if (found.length > 0) return { reason: found.slice(0, 3).join(', '), status: 'ok' };

    if (VAGUE_DISTRESS.some(p => t.includes(p))) return { reason: 'General Checkup', status: 'ok' };

    // "mujhe X ki takleef hai" where X is unknown -> keep X as the reason
    const m = t.match(/(?:takleef|तकलीफ|problem|समस्या|dikkat|दिक्कत|dard|दर्द)\s*(?:hai|है)?\s*(?:liye|लिए)?\s*(.{0,30})/i);
    if (m && m[1] && normalize(m[1]).length > 2 && !/^(hai|है|nahi|नहीं|kuch|कुछ)$/i.test(normalize(m[1]))) {
      return { reason: normalize(m[1]).replace(/[।.,]$/, ''), status: 'ok' };
    }

    // patient is being evasive: "kuch nahi", "nahi batana", "aap batao"
    if (/kuch\s*(nahi|नहीं)|nahi\s*bata|नहीं\s*बता|aap\s*bata|आप\s*बता/.test(t)) {
      return { reason: 'Not specified', status: 'ok' };
    }
    return { reason: null, status: 'none' };
  }

  // ----------------------------------------------------- CALL CLASSIFICATION
  const WRONG_NUMBER = [
    'galat number', 'galat no', 'wrong number', 'galti se', 'galti se mila', 'koi nahi chahiye',
    'appointment nahi chahiye', 'nahi chahiye appointment', 'cancel karo', 'cancel kar do', 'band karo',
    'rakhna nahi', 'mat karo call', 'call mat karo', 'mujhe nahi chahiye', 'गलत नंबर', 'गलत नम्बर',
    'नहीं चाहिए', 'बंद करो', 'काटो', 'मत करो', 'cancel', 'stop calling', 'do not call', 'wrong no',
  ];

  const EMERGENCY = [
    'chest pain', 'seene me dard', 'seene mein dard', 'सीने में दर्द', 'heart attack', 'हार्ट अटैक',
    'saans nahi', 'सांस नहीं', 'dam ghut', 'दम घुट', 'behosh', 'बेहोश', 'unconscious', 'khoon',
    'खून', 'bleeding', 'accident', 'एक्सीडेंट', 'durghatna', 'दुर्घटना', 'emergency', 'इमरजेंसी',
    'bahut zyada dard', 'asahniya dard', 'असहनीय दर्द', 'paralysis', 'लकवा', 'fits', 'मिर्गी', 'दौरा',
    'zeher', 'ज़हर', 'जहर', 'poison', 'suicide', 'आत्महत्या', 'atmyahathya',
  ];

  const CALLBACK_LATER = [
    'baad me call', 'baad mein call', 'बाद में कॉल', 'abhi busy', 'अभी बिज़ी', 'busy hoon',
    'call you later', 'later call', 'phone rakhta', 'phone rakhti', 'baad me baat',
  ];

  const NOISE_ONLY = [
    'hello', 'hallo', 'helo', 'हेलो', 'hmm', 'hmmm', 'hmmmm', 'uh', 'umm', 'um', 'aaa', 'aaaa',
    'haan', 'han', 'ha', 'हाँ', 'हां', 'hn', 'ok', 'okay', 'theek', 'thik', 'हूँ', 'हूं', 'hm',
    'kya', 'क्या', 'suno', 'सुनो', 'bolo', 'बोलो', 'speak', 'are you there', 'are you there?',
    'noise', 'background noise', 'inaudible', 'silence', 'beep', 'static',
  ];

  function stripNoise(t) {
    let s = t
      .replace(/\[[^\]]*\]/g, ' ')     // [Background noise]
      .replace(/\([^)]*\)/g, ' ')      // (inaudible)
      .replace(/[.,!?।\-]+/g, ' ')
      .replace(/\s+/g, ' ')
      .trim();
    return s;
  }

  function isNoise(t) {
    const s = stripNoise(t);
    if (!s) return true;
    if (s.length <= 2) return true;
    if (NOISE_ONLY.includes(s)) return true;
    // "hello hello hello", "hmm hmm"
    const parts = s.split(' ').filter(Boolean);
    if (parts.length <= 3 && parts.every(p => NOISE_ONLY.includes(p))) return true;
    return false;
  }

  function detectAny(t, list) { return list.some(w => t.includes(w)); }

  // ------------------------------------------------------------------ MERGE
  /**
   * @param {object} ctx {
   *   transcript, phone, call_sid, attempt, asked_field, prev: {...}, today
   * }
   */
  function extract(ctx) {
    ctx = ctx || {};
    const today = startOfDay(ctx.today || new Date());
    const raw = normalize(ctx.transcript);
    const t = raw.toLowerCase();
    const prev = ctx.prev || {};
    const askedField = ctx.asked_field || null;

    const out = {
      // ---- raw echo ----
      raw_text: raw,
      phone: ctx.phone || '',
      call_sid: ctx.call_sid || '',
      attempt: parseInt(ctx.attempt || '0', 10) || 0,
      asked_field: askedField,

      // ---- answers ----
      name: null, date: null, date_iso: null, date_speech: null,
      time_slot: null, time_slot_display: null, time_slot_speech: null,
      reason: null, booking_for: 'Self',

      // ---- flags ----
      is_wrong_number: false, is_emergency: false, is_noise: false, is_callback: false,
      hint: null, notes: [],
    };

    // ---- 1. call classification (before anything else) ----
    if (detectAny(t, EMERGENCY)) { out.is_emergency = true; }
    else if (detectAny(t, WRONG_NUMBER) && stripNoise(t).length > 2) { out.is_wrong_number = true; }
    else if (detectAny(t, CALLBACK_LATER)) { out.is_callback = true; }
    else if (isNoise(t)) { out.is_noise = true; }

    if (out.is_emergency || out.is_wrong_number || out.is_callback || out.is_noise) {
      // still remember what we already collected
      out.name = prev.name || null;
      out.date = prev.date || null;
      out.date_iso = prev.date_iso || null;
      out.date_speech = prev.date_speech || null;
      out.time_slot = prev.time_slot || null;
      out.time_slot_display = prev.time_slot_display || null;
      out.time_slot_speech = prev.time_slot_speech || null;
      out.reason = prev.reason || null;
      out.booking_for = prev.booking_for || 'Self';
      out.missing = computeMissing(out);
      out.all_collected = false;
      out.status = 'Incomplete';
      return finalize(out);
    }

    // ---- 2. relation ("meri mummy ke liye") ----
    const relation = detectRelation(t);
    out.booking_for = relation !== 'Self' ? relation : (prev.booking_for && prev.booking_for !== 'Self' ? prev.booking_for : 'Self');

    // ---- 3. name ----
    let name = extractName(raw);           // raw keeps original capitalisation: "Priya Sharma"
    if (!name && askedField === 'name' && !nameWasExplicitlyCleared(t)) {
      const candidate = cleanName(stripNoise(raw));
      if (candidate && candidate.split(' ').length <= 2) name = candidate;
    }
    if (name) out.name = name;
    else if (askedField === 'name' && looksLikeFailedName(t)) out.name = null;   // caller tried, we didn't get it
    else out.name = prev.name || null;

    // ---- 4. date ----
    const dateRes = parseDate(t, today);
    if (dateRes.status === 'ok') {
      out.date = dateRes.info.value; out.date_iso = dateRes.info.iso; out.date_speech = dateRes.info.speech;
    } else if (dateRes.status !== 'none') {
      out.hint = dateRes.status;               // past_date / closed_day / invalid_date / too_far
      out.name = out.name || prev.name || null;
      out.date = null;
      out.notes.push('date_rejected:' + dateRes.status);
    } else {
      out.date = prev.date || null; out.date_iso = prev.date_iso || null; out.date_speech = prev.date_speech || null;
      if (askedField === 'date' && looksLikeDateAttempt(t)) {
        out.hint = 'invalid_date';
        out.date = null; out.date_iso = null; out.date_speech = null;
      }
    }

    // ---- 5. time ----
    const timeRes = parseTime(t);
    if (timeRes.status === 'ok') {
      out.time_slot = timeRes.slot;
      out.time_slot_display = timeRes.display;
      out.time_slot_speech = timeRes.speech;
    } else if (timeRes.status === 'out_of_hours' || timeRes.status === 'invalid_time') {
      out.hint = timeRes.status === 'out_of_hours' ? 'out_of_hours' : 'invalid_time';
      out.time_slot = null; out.time_slot_display = null; out.time_slot_speech = null;
      out.notes.push('time_rejected:' + timeRes.status);
    } else {
      out.time_slot = prev.time_slot || null;
      out.time_slot_display = prev.time_slot_display || prev.time_slot || null;
      out.time_slot_speech = prev.time_slot_speech || null;
      if (askedField === 'time_slot' && looksLikeTimeAttempt(t) && !out.time_slot) {
        out.hint = 'invalid_time';
      }
    }

    // ---- 6. reason ----
    const reasonRes = extractReason(t);
    if (reasonRes.status === 'ok') out.reason = reasonRes.reason;
    else out.reason = prev.reason || null;

    // ---- 7. missing slots + progress ----
    out.missing = computeMissing(out);
    const prevMissingCount = parseInt(ctx.prev_missing_count, 10);
    out.progressed = out.missing.length < (isNaN(prevMissingCount) ? out.missing.length : prevMissingCount);
    out.all_collected = out.missing.length === 0;
    out.status = out.all_collected ? 'Confirmed' : 'Incomplete';
    out.completion = Math.round(((4 - out.missing.length) / 4) * 100);
    return finalize(out);
  }

  /** Fills in the "spoken" versions when only the short value survived a URL round-trip. */
  function finalize(out) {
    if (out.date && !out.date_iso) out.date_iso = isoForDateValue(out.date);
    if (out.date && !out.date_speech) out.date_speech = speechForDateValue(out.date);
    if (out.time_slot && !out.time_slot_speech) out.time_slot_speech = speechForSlot(out.time_slot);
    if (out.time_slot && !out.time_slot_display) out.time_slot_display = out.time_slot;
    return out;
  }

  function looksLikeFailedName(t) {
    return /naam|नाम|बोल रह|bol rah|mera name|my name/.test(t);
  }
  function nameWasExplicitlyCleared(t) {
    return /naam nahi|नाम नहीं|naam galat|naam bhool/.test(t);
  }

  function computeMissing(out) {
    const missing = [];
    if (!out.name) missing.push({ field: 'name', hindi: 'आपका पूरा नाम' });
    if (!out.date) missing.push({ field: 'date', hindi: 'अपॉइंटमेंट की तारीख' });
    if (!out.time_slot) missing.push({ field: 'time_slot', hindi: 'समय — सुबह, दोपहर या शाम' });
    if (!out.reason) missing.push({ field: 'reason', hindi: 'तकलीफ़ का कारण' });
    return missing;
  }

  // -------------------------------------------------------------- QUESTIONS
  const QUESTIONS = {
    name: [
      'क्षमा करें, मुझे आपका नाम सुनाई नहीं दिया। कृपया अपना पूरा नाम बताएं।',
      'जैसे — प्रिया शर्मा। अब बताइए, आपका नाम क्या है?',
      'सिर्फ अपना नाम बोलिए — जैसे "प्रिया"।',
    ],
    date: [
      'धन्यवाद! अब बताइए, आप किस तारीख को आना चाहते हैं?',
      'जैसे — कल, या 25 जून। किस दिन आना है?',
      'सिर्फ दिन बोलिए — जैसे "कल" या "परसों"।',
    ],
    time_slot: [
      'ठीक है! आप कौन सा समय चाहते हैं — सुबह, दोपहर या शाम?',
      'जैसे — सुबह 10 बजे। कब आना है?',
      'सिर्फ समय बोलिए — जैसे "सुबह 10 बजे"।',
    ],
    reason: [
      'कृपया बताइए, आपको किस समस्या के लिए डॉक्टर से मिलना है?',
      'जैसे — बुखार, खांसी या दर्द। क्या तकलीफ़ है?',
      'सिर्फ तकलीफ़ बोलिए — जैसे "बुखार"।',
    ],
  };

  const HINTS = {
    past_date: 'यह तारीख बीत चुकी है। कृपया आगे की तारीख बताइए। ',
    closed_day: 'उस दिन क्लिनिक बंद रहता है। कृपया कोई और दिन बताइए। ',
    invalid_date: 'क्षमा करें, तारीख समझ नहीं आई। ',
    too_far: 'इतनी दूर की तारीख नहीं दे सकते। ',
    out_of_hours: 'क्लिनिक सुबह 9 बजे से रात 9 बजे तक खुलता है। ',
    invalid_time: 'समय समझ नहीं आया। ',
    slot_full: 'यह समय भर चुका है, कृपया दूसरा समय चुनिए। ',
    already_booked: 'इसी समय के लिए आपकी अपॉइंटमेंट पहले से बुक है। ',
  };

  function questionFor(field, attempt) {
    const list = QUESTIONS[field] || ['कृपया अपना ' + field + ' बताइए।'];
    const idx = Math.min(Math.max((attempt || 1) - 1, 0), list.length - 1);
    return list[idx];
  }

  /** Which field are we about to ask about? (first missing) */
  function nextField(missing) {
    return missing && missing.length ? missing[0].field : null;
  }

  // ------------------------------------------------------------- TWIML BUILD
  const VOICE_LANG = 'language="hi-IN"';

  function wrapTwiml(inner) { return '<?xml version="1.0" encoding="UTF-8"?><Response>' + inner + '</Response>'; }

  function say(text) { return '<Say ' + VOICE_LANG + '>' + escapeXml(text) + '</Say>'; }

  function gather(sayText, actionUrl) {
    return '<Gather input="speech" ' + VOICE_LANG + ' speechTimeout="auto" actionOnEmptyResult="true" action="' +
      escapeXml(actionUrl) + '" method="POST">' + say(sayText) + '</Gather>';
  }

  function hangup() { return '<Hangup/>'; }

  return {
    CONFIG, normalize, escapeXml, toNumber, cleanName, extractName, detectRelation,
    parseDate, parseTime, extractReason, isNoise, looksLikeDateAttempt, looksLikeTimeAttempt,
    extract, computeMissing, questionFor, nextField, HINTS, QUESTIONS,
    fmtDate, fromEnDate, speechForDateValue, isoForDateValue, speechForSlot, finalize,
    wrapTwiml, say, gather, hangup,
  };
})();

if (typeof module !== 'undefined' && module.exports) module.exports = BotEngine;
if (typeof globalThis !== 'undefined') globalThis.BotEngine = BotEngine;
